effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      float rand(vec2 co, float seed) {
          return fract(sin(dot(co, vec2(12.9898, 78.233) + fract(seed))) * 43758.5453);
      }

      vec3 get_rgb_noise(vec2 uv, float seed) {
          return vec3(
              rand(uv, seed),
              rand(uv, seed + 0.33),
              rand(uv, seed + 0.66)
          );
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);
     float time = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          vec2 uv = umefx;

          vec2 size = SZX;
          // vec2 size = vec2(800, 600);
          vec2 coordinate = vec2(uv * size);
          float blockSize = size.x / 8.0;
          // assign this coordinate to a specific block made of 16 pixels
          vec2 block = floor(coordinate.xy / vec2(blockSize));
          vec2 uv_noise = block / vec2(blockSize);
          uv_noise += floor(vec2(time) * vec2(1234.0, 3543.0)) / vec2(blockSize);
          uv_noise = fract(uv_noise);

          // increase the last number to have more blocks
          float block_thresh = pow(fract(time * 1236.0453), 2.0) * 0.1;
          // increase the last number to have more lines
          float line_thresh = pow(fract(time * 2236.0453), 3.0) * 0.3;

          vec2 uv_r = uv, uv_g = uv, uv_b = uv;

          // glitch some blocks and lines
          if (get_rgb_noise(uv_noise, time).r < block_thresh || get_rgb_noise(vec2(uv_noise.y, 0.0), time).g < line_thresh) {
              vec2 dist = (uv_noise - 0.5) * 0.3;
              uv_r += dist * 0.1;
              uv_g += dist * 0.2;
              uv_b += dist * 0.125;
          }

          vec4 color = vec4(1);

          color.r = texColor.r;
          color.g = texColor.g;
          color.b = texColor.b;

          // color.r = getFromColor(uv_r).r;
          // color.g = getFromColor(uv_g).g;
          // color.b = getFromColor(uv_b).b;

          // loose luma for some blocks
          if (get_rgb_noise(uv_noise, time).g < block_thresh)
              color.rgb = color.ggg;

          // discolor block lines
          if (get_rgb_noise(vec2(uv_noise.y, 0.0), time).b * 3.5 < line_thresh)
              color.rgb = vec3(0.0, dot(color.rgb, vec3(1.0)), 0.0);

          // interleave lines in some blocks
          if (get_rgb_noise(uv_noise, time).g * 1.5 < block_thresh ||
                  get_rgb_noise(vec2(uv_noise.y, 0.0), time).g * 2.5 < line_thresh) {
              float line = fract(coordinate.y / 12.0);
              vec3 mask = vec3(3.0, 0.0, 0.0);
              if (line > 0.333)
                  mask = vec3(0.0, 3.0, 0.0);
              if (line > 0.666)
                  mask = vec3(0.0, 0.0, 3.0);

              color.xyz *= mask;
              color = vec4(min(color.x, 1.0), min(color.y, 1.0), min(color.z, 1.0), 1.0);
          }

          fragColor = color;

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
